import{shellQuote}from"./shell.js";async function validateRepositoryRoot(e,t){if(!t.startsWith(`/`))throw Error(`root must be an absolute sandbox path`);let n=await realPath(e,e.resolvePath(``),`sandbox workspace`),r=await realPath(e,t,`root`);if(!(n===`/`||r===n||r.startsWith(`${n}/`)))throw Error(`root resolves outside the workspace ${n}: ${r}`);let i=await e.run({command:`git -C ${shellQuote(r)} rev-parse --show-toplevel`});if(i.exitCode!==0||i.stdout.trim()!==r)throw Error(`root is not a git work tree root: ${t}`);return r}async function realPath(e,t,n){let r=await e.run({command:`realpath -e -z -- ${shellQuote(t)}`});if(r.exitCode!==0){let e=r.stderr.trim()||r.stdout.trim()||`no command output`;throw Error(`${n} could not be resolved: ${e.slice(0,2e3)}`)}let i=r.stdout.endsWith(`\0`)?r.stdout.slice(0,-1):r.stdout;if(i.length===0||i.includes(`\0`))throw Error(`${n} returned an invalid realpath`);return i}export{validateRepositoryRoot};